// Family worship sessions reuse the existing shared notes and photo backup.
const FAMILY_SESSION_BOOK='family-session-v1',FAMILY_PHOTO_BOOK='family-photo-v1';
let familyPin='',familyPhotoCache=new Map(),familyRevision=0,familyHistoryQuery='',familySearchOpen=false;
function familyInternal(n){return n?.book===FAMILY_SESSION_BOOK||n?.book===FAMILY_PHOTO_BOOK}
function familyDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function familyParseDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return null;const [y,m,d]=value.split('-').map(Number),v=new Date(y,m-1,d,12);return familyDate(v)===value?v:null}
function familyAddDays(value,n){const d=familyParseDate(value);if(!d)return '';d.setDate(d.getDate()+n);return familyDate(d)}
function familyNextTuesday(){const now=new Date();now.setHours(12,0,0,0);now.setDate(now.getDate()+(2-now.getDay()+7)%7);return familyDate(now)}
function familyDayLabel(value,showYear=false){const d=familyParseDate(value);return d?`${showYear?d.getFullYear()+'년 ':''}${d.getMonth()+1}월 ${d.getDate()}일 · ${['일','월','화','수','목','금','토'][d.getDay()]}요일`:''}
function familyTimeLabel(value){if(!/^\d{2}:\d{2}$/.test(value||''))return '';const [h,m]=value.split(':').map(Number);return `${h<12?'오전':'오후'} ${h%12||12}:${String(m).padStart(2,'0')}`}
function familyDefaults(anchor){return {version:1,date:anchor,time:'',topic:'',participants:['민수','보라'],preparation:'',common:'',mine:'',bora:'',url:'',completed:false,cover:'',order:[]}}
function familySessionNote(anchor){return notes.find(n=>n.book===FAMILY_SESSION_BOOK&&n.person==='@family-session:'+anchor)||null}
function familySession(anchor){const note=familySessionNote(anchor),fallback=familyDefaults(anchor);if(!note)return fallback;try{const x=JSON.parse(note.body);if(x.version!==1||!familyParseDate(x.date))return fallback;const result={...fallback,date:x.date,completed:x.completed===true,participants:Array.isArray(x.participants)?x.participants.filter(v=>typeof v==='string').slice(0,30):fallback.participants,order:Array.isArray(x.order)?x.order.filter(v=>typeof v==='string'):[]};for(const k of ['time','topic','preparation','common','mine','bora','url','cover'])if(typeof x[k]==='string')result[k]=x[k];return result}catch{return fallback}}
function familySessionAnchors(){return [...new Set(notes.filter(n=>n.book===FAMILY_SESSION_BOOK&&/^@family-session:\d{4}-\d{2}-\d{2}$/.test(n.person)).map(n=>n.person.slice(16)).filter(familyParseDate))]}
function familyPhotoNotes(anchor){const list=notes.filter(n=>n.book===FAMILY_PHOTO_BOOK&&n.person==='@family-photo:'+anchor),order=familySession(anchor).order;return list.sort((a,b)=>{const ai=order.indexOf(a.id),bi=order.indexOf(b.id);return (ai<0?1e9:ai)-(bi<0?1e9:bi)||String(a.created_at).localeCompare(String(b.created_at))})}
function familyNext(){const today=familyDate(new Date()),anchors=familySessionAnchors(),saved=anchors.map(anchor=>({anchor,data:familySession(anchor)})).filter(x=>x.data.date>=today&&!x.data.completed);let candidate=familyNextTuesday();while(anchors.includes(candidate))candidate=familyAddDays(candidate,7);saved.push({anchor:candidate,data:familySession(candidate)});return saved.sort((a,b)=>a.data.date.localeCompare(b.data.date)||a.anchor.localeCompare(b.anchor))[0]}
function familyHomePreview(){const s=familyNext();return s?.data.topic?`${familyDayLabel(s.data.date)} · ${s.data.topic}`:''}
function familySessionLink(anchor){return '#/family/session/'+encodeURIComponent(anchor)}
function familyNames(items){return items.map(name=>name==='민수'?personIdentity('mine'):name==='보라'?personIdentity('bora'):`<span class="family-guest">${esc(name)}</span>`).join('')}
function familyPhotoSource(id){if(!familyPhotoCache.has(id)){const pending=getNoteImages(id).then(imgs=>imgs[0]?.src||'').catch(err=>{familyPhotoCache.delete(id);throw err});familyPhotoCache.set(id,pending)}return familyPhotoCache.get(id)}
function familyFillPhotos(root){root.querySelectorAll('[data-family-photo-src]').forEach(async el=>{try{const src=await familyPhotoSource(el.dataset.familyPhotoSrc);if(!el.isConnected||!src)return;el.src=src;el.hidden=false}catch{if(el.isConnected)el.alt='사진을 불러오지 못했어요'}})}
function familyThumb(anchor){const list=familyPhotoNotes(anchor),cover=familySession(anchor).cover,first=list.find(x=>x.id===cover)||list[0];return first?`<img class="family-list-thumb" data-family-photo-src="${esc(first.id)}" alt="" hidden>`:''}
function familyView(){
 const next=familyNext(),today=familyDate(new Date()),history=familySessionAnchors().map(anchor=>({anchor,data:familySession(anchor)})).filter(x=>x.anchor!==next.anchor&&(x.data.date<today||x.data.completed)).sort((a,b)=>b.data.date.localeCompare(a.data.date)||b.anchor.localeCompare(a.anchor));
 const upcoming=familySessionAnchors().map(anchor=>({anchor,data:familySession(anchor)})).filter(x=>x.anchor!==next.anchor&&x.data.date>=today&&!x.data.completed).sort((a,b)=>a.data.date.localeCompare(b.data.date));
 const old=notes.filter(n=>n.person.startsWith('@family:'));
 $('#app').innerHTML=`<div class="workspace family-page"><div class="family-head"><h1 class="people-title">가족 숭배</h1><button type="button" class="action-icon" id="family-next-add" aria-label="다음 가족 숭배 준비" title="다음 가족 숭배 준비">${UI_PLUS}</button></div><a class="family-next" href="${familySessionLink(next.anchor)}"><div class="family-next-label">다가오는 가족 숭배</div><div class="family-next-date">${esc(familyDayLabel(next.data.date))}${next.data.time?` <span>${esc(familyTimeLabel(next.data.time))}</span>`:''}</div><h2>${esc(next.data.topic||'주제 정하기')}</h2><div class="family-people">${familyNames(next.data.participants)}</div>${next.data.preparation?`<div class="family-prep"><span>준비</span><p>${esc(next.data.preparation)}</p></div>`:''}<span class="family-next-arrow" aria-hidden="true">→</span></a>${upcoming.length?`<section class="family-history"><h2>예정</h2>${upcoming.map(familyListItem).join('')}</section>`:''}${history.length?`<section class="family-history"><div class="family-history-head"><h2>지난 기록</h2>${history.length?`<button type="button" class="tool-icon family-search-toggle" id="family-search-toggle" aria-label="지난 기록 검색" aria-expanded="${familySearchOpen}" title="지난 기록 검색">${uiIcon('<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>')}</button>`:''}</div><label class="family-search" ${familySearchOpen?'':'hidden'}><span class="sr-only">지난 기록 검색</span><input id="family-history-search" type="search" placeholder="주제나 배운 점 검색" value="${esc(familyHistoryQuery)}"></label><div id="family-history-results">${familyHistory(familyFilterHistory(history,familyHistoryQuery))||(familyHistoryQuery.trim()?'<p class="family-no-results">검색 결과가 없어요.</p>':'')}</div></section>`:''}${old.length?`<section class="family-history family-legacy"><h2>기존 기록</h2>${old.map(n=>`<a class="family-history-row" href="${idHash(n.person)}?note=${encodeURIComponent(n.id)}"><span><small>${esc(n.person.slice(8))}</small><strong>${esc(n.title)}</strong></span><span aria-hidden="true">→</span></a>`).join('')}</section>`:''}</div><a class="back bottom-back" href="#/home">← 처음</a>`;
 $('#family-search-toggle')?.addEventListener('click',()=>{familySearchOpen=!familySearchOpen;const label=$('.family-search');label.hidden=!familySearchOpen;$('#family-search-toggle').setAttribute('aria-expanded',String(familySearchOpen));if(familySearchOpen)$('#family-history-search').focus();else{familyHistoryQuery='';$('#family-history-search').value='';$('#family-history-results').innerHTML=familyHistory(history);familyFillPhotos($('#family-history-results'))}});$('#family-history-search')?.addEventListener('input',e=>{familyHistoryQuery=e.target.value;const filtered=familyFilterHistory(history,familyHistoryQuery);$('#family-history-results').innerHTML=familyHistory(filtered)||(familyHistoryQuery.trim()?'<p class="family-no-results">검색 결과가 없어요.</p>':'');familyFillPhotos($('#family-history-results'))});$('#family-next-add').onclick=()=>{const anchors=familySessionAnchors();let anchor=familyAddDays(next.anchor,7);while(anchors.includes(anchor))anchor=familyAddDays(anchor,7);location.hash=familySessionLink(anchor)};familyFillPhotos($('#app'));
}
function familyFilterHistory(items,query){const q=query.trim().toLocaleLowerCase();return q?items.filter(({data})=>[data.topic,data.preparation,data.common,data.mine,data.bora,...data.participants].join(' ').toLocaleLowerCase().includes(q)):items}
function familyHistory(items){let last='';return items.map(item=>{const year=item.data.date.slice(0,4),heading=year!==last?`<h3 class="family-year">${esc(year)}</h3>`:'';last=year;return heading+familyListItem(item)}).join('')}
function familyListItem(item){const {anchor,data}=item,preview=data.common||data.mine||data.bora||'';return `<a class="family-history-row" href="${familySessionLink(anchor)}"><span class="family-history-text"><small>${esc(familyDayLabel(data.date))}</small><strong>${esc(data.topic||'가족 숭배')}</strong>${preview?`<span>${esc(preview)}</span>`:''}</span>${familyThumb(anchor)}<span class="family-row-arrow" aria-hidden="true">→</span></a>`}
function familySessionView(anchor){
 if(!familyParseDate(anchor)||familyParseDate(anchor).getDay()!==2){familyView();return}const data=familySession(anchor),pictures=familyPhotoNotes(anchor),safe=safeUrl(data.url),imageItems=pictures.map((n,i)=>`<div class="family-photo"><button type="button" class="family-photo-open" data-family-open-photo="${esc(n.id)}" aria-label="사진 ${i+1} 확대"><img data-family-photo-src="${esc(n.id)}" alt="가족 숭배 사진 ${i+1}" hidden></button><button type="button" class="family-photo-menu tool-icon" data-family-photo-menu="${esc(n.id)}" aria-label="사진 ${i+1} 관리">${uiIcon('<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>')}</button>${data.cover===n.id?'<span class="family-photo-cover">대표</span>':''}</div>`).join('');
 $('#app').innerHTML=`<div class="workspace family-detail"><div class="family-detail-head"><div><p class="family-detail-date">${esc(familyDayLabel(data.date))}${data.time?` · ${esc(familyTimeLabel(data.time))}`:''}</p><h1>${esc(data.topic||'주제 정하기')}</h1></div><button type="button" class="action-icon" id="family-edit-plan" aria-label="가족 숭배 일정 수정" title="일정 수정">${UI_PENCIL}</button></div><div class="family-detail-people">${familyNames(data.participants)}</div>${data.preparation?`<section class="family-detail-section"><h2>준비</h2><p class="family-text">${esc(data.preparation)}</p></section>`:''}${safe?`<p class="family-reference"><a href="${esc(studyBibleResourceUrl(safe))}" target="_blank" rel="noopener noreferrer">자료 ↗</a></p>`:''}<section class="family-detail-section"><div class="family-section-head"><h2>사진</h2><div class="family-photo-tools">${pictures.length>1?`<button type="button" class="action-icon" id="family-photo-arrange" aria-label="사진 순서와 대표 사진 정리" title="사진 정리">${uiIcon('<path d="M4 7h12m-3-3 3 3-3 3M20 17H8m3-3-3 3 3 3"/>')}</button>`:''}<button type="button" class="action-icon" id="family-photo-add" aria-label="사진 추가" title="사진 추가">${UI_PLUS}</button></div><input id="family-photo-input" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple hidden></div>${pictures.length?`<div class="family-photo-grid" data-count="${pictures.length}">${imageItems}</div>`:''}</section><section class="family-detail-section"><div class="family-section-head"><h2>배운 점</h2><button type="button" class="action-icon" id="family-edit-reflection" aria-label="배운 점 작성 또는 수정" title="배운 점 작성 또는 수정">${data.common||data.mine||data.bora?UI_PENCIL:UI_PLUS}</button></div>${data.common?`<p class="family-text">${esc(data.common)}</p>`:''}${data.mine?`<div class="family-reflection"><span>${personIdentity('mine')}</span><p class="family-text">${esc(data.mine)}</p></div>`:''}${data.bora?`<div class="family-reflection"><span>${personIdentity('bora')}</span><p class="family-text">${esc(data.bora)}</p></div>`:''}</section>${familySessionNote(anchor)?`<button type="button" class="family-remove tool-icon" id="family-remove" aria-label="회차 삭제" title="회차 삭제">${uiIcon('<path d="M4 7h16M10 11v6m4-6v6M6 7l1 13h10l1-13M9 7V4h6v3"/>')}</button>`:''}</div><a class="back bottom-back" href="#/family">← 가족 숭배</a>`;
 $('#family-edit-plan').onclick=()=>familyOpenForm(anchor,'plan');$('#family-edit-reflection').onclick=()=>familyOpenForm(anchor,'reflection');$('#family-remove')?.addEventListener('click',()=>familyRemoveSession(anchor));$('#family-photo-arrange')?.addEventListener('click',()=>familyArrangePhotos(anchor));$('#family-photo-add').onclick=()=>$('#family-photo-input').click();$('#family-photo-input').onchange=e=>{const files=Array.from(e.target.files);e.target.value='';if(files.length)familyOpenUpload(anchor,files)};
 document.querySelectorAll('[data-family-open-photo]').forEach(b=>b.onclick=()=>familyOpenGallery(anchor,b.dataset.familyOpenPhoto));document.querySelectorAll('[data-family-photo-menu]').forEach(b=>b.onclick=()=>familyPhotoActions(anchor,b.dataset.familyPhotoMenu));familyFillPhotos($('#app'));
}
function familyDialog(title,content){familyRevision++;const d=document.createElement('dialog');d.className='family-dialog';d.dataset.origin=location.hash;d.innerHTML=`<div class="family-sheet"><div class="family-sheet-head"><h2>${esc(title)}</h2><button type="button" class="tool-icon family-dialog-close" aria-label="닫기">${uiIcon('<path d="M18 6 6 18M6 6l12 12"/>')}</button></div>${content}</div>`;document.body.append(d);let busy=false;d.setBusy=v=>{busy=v;d.classList.toggle('is-busy',v);d.setAttribute('aria-busy',String(v));d.querySelectorAll('button,input,textarea').forEach(x=>x.disabled=v)};d.canClose=()=>!busy&&(!d.isDirty?.()||confirm('작성 중인 내용이 있어요. 닫을까요?'));d.querySelector('.family-dialog-close').onclick=()=>{if(d.canClose())d.close()};d.addEventListener('cancel',e=>{if(!d.canClose())e.preventDefault()});d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();return d}
function familyRouteGuard(){const d=document.querySelector('dialog.family-dialog[open]');if(!d||location.hash===d.dataset.origin)return true;if(d.canClose()){d.close();return true}history.replaceState(null,'',d.dataset.origin||'#/family');return false}
window.addEventListener('beforeunload',e=>{const d=document.querySelector('dialog.family-dialog[open]');if(d?.isDirty?.()){e.preventDefault();e.returnValue=''}});
function familyPasswordField(){return familyPin?'':`<label class="family-field">비밀번호<input name="password" type="password" inputmode="numeric" autocomplete="current-password" required></label>`}
function familyGetPassword(d){return familyPin||d.querySelector('[name=password]')?.value||''}
async function familyReloadNotes(){notes=await getAll('study_notes','id,person,author,title,body,created_at,updated_at,verse,book,topic,reference_url')}
async function familySaveMeta(anchor,data,password,expected=familySessionNote(anchor)){
 const body=JSON.stringify(data);if(body.length>19000)throw Error('작성한 내용이 너무 길어요.');const payload={person:'@family-session:'+anchor,author:'mine',title:(data.topic||'가족 숭배').slice(0,100),body,book:FAMILY_SESSION_BOOK,verse:'',topic:'',reference_url:'',images:[],file_paths:[]};
 if(expected){payload.id=expected.id;payload.expected_updated_at=expected.updated_at||null;await change('update',payload,password)}else{try{await change('create',payload,password)}catch(e){if(/unique|duplicate|중복/i.test(e.message))throw Error('다른 기기에서 먼저 준비했어요. 다시 열어 확인해 주세요.');throw e}}
}
function familyOpenForm(anchor,mode){const data=familySession(anchor),expected=familySessionNote(anchor),plan=mode==='plan';const content=plan?`<div class="family-date-fields"><label class="family-field">날짜<input type="date" name="date" value="${esc(data.date)}" required></label><label class="family-field">시간<input type="time" name="time" value="${esc(data.time)}"></label></div><label class="family-field">주제<input name="topic" maxlength="100" value="${esc(data.topic)}"></label><fieldset class="family-attendees"><legend>참석자</legend><div class="family-attendee-options"><label><input type="checkbox" name="memberMine" ${data.participants.includes('민수')?'checked':''}>${personIdentity('mine')}<span>민수</span></label><label><input type="checkbox" name="memberBora" ${data.participants.includes('보라')?'checked':''}>${personIdentity('bora')}<span>보라</span></label></div><input class="family-guest-input" name="guests" maxlength="300" value="${esc(data.participants.filter(x=>x!=='민수'&&x!=='보라').join(', '))}" placeholder="다른 참석자 (쉼표로 구분)"></fieldset><label class="family-field">준비사항<textarea name="preparation" rows="3" maxlength="3000">${esc(data.preparation)}</textarea></label><details class="family-optional" ${data.url?'open':''}><summary>자료 링크</summary><label class="family-field"><span class="sr-only">자료 링크</span><input name="url" type="url" maxlength="2000" value="${esc(data.url)}" placeholder="https://"></label></details>`:`<label class="family-field">함께<textarea name="common" rows="4" maxlength="4000">${esc(data.common)}</textarea></label><details class="family-optional" ${data.mine||data.bora?'open':''}><summary>각자의 생각</summary><label class="family-field">민수<textarea name="mine" rows="3" maxlength="4000">${esc(data.mine)}</textarea></label><label class="family-field">보라<textarea name="bora" rows="3" maxlength="4000">${esc(data.bora)}</textarea></label></details>`;
 const d=familyDialog(plan?'일정':'배운 점',`<form class="family-form">${content}${familyPasswordField()}<p class="family-form-error" role="alert"></p><button class="primary family-save" type="submit">저장</button></form>`),form=d.querySelector('form'),snapshot=()=>JSON.stringify([...form.elements].filter(el=>el.name&&el.name!=='password').map(el=>[el.name,el.type==='checkbox'?el.checked:el.value])),initial=snapshot(),draftKey='family-draft-v1:'+anchor+':'+mode;try{const saved=JSON.parse(sessionStorage.getItem(draftKey)||'null');if(saved){for(const [key,value] of Object.entries(saved))if(form.elements[key]&&key!=='password'){if(form.elements[key].type==='checkbox')form.elements[key].checked=value;else form.elements[key].value=value;}if(saved.mine||saved.bora||saved.url)form.querySelector('.family-optional')?.setAttribute('open','')}}catch{}d.isDirty=()=>snapshot()!==initial;form.addEventListener('input',()=>{try{const values=Object.fromEntries([...form.elements].filter(el=>el.name&&el.name!=='password').map(el=>[el.name,el.type==='checkbox'?el.checked:el.value]));sessionStorage.setItem(draftKey,JSON.stringify(values))}catch{}});d.addEventListener('close',()=>{try{sessionStorage.removeItem(draftKey)}catch{}});form.onsubmit=async e=>{e.preventDefault();const password=familyGetPassword(d),field=name=>form.elements[name].value,updated={...data};if(plan){updated.date=field('date');updated.time=field('time');updated.topic=field('topic').trim();updated.participants=[...(form.elements.memberMine.checked?['민수']:[]),...(form.elements.memberBora.checked?['보라']:[]),...field('guests').split(',').map(x=>x.trim()).filter(Boolean)].slice(0,30);updated.preparation=field('preparation').trim();updated.url=field('url').trim();if(!familyParseDate(updated.date)){d.querySelector('.family-form-error').textContent='날짜를 확인해 주세요.';return}if(updated.url&&!safeUrl(updated.url)){d.querySelector('.family-form-error').textContent='자료 링크를 확인해 주세요.';return}}else{updated.common=field('common').trim();updated.mine=field('mine').trim();updated.bora=field('bora').trim()}
 d.setBusy(true);d.querySelector('.family-form-error').textContent='';try{await familySaveMeta(anchor,updated,password,expected);familyPin=password;await familyReloadNotes();d.close();if(location.hash===familySessionLink(anchor))familySessionView(anchor)}catch(err){d.querySelector('.family-form-error').textContent=err.message||'저장하지 못했어요.';if(/다른 기기/.test(err.message||''))await familyReloadNotes().catch(()=>{})}finally{if(d.isConnected)d.setBusy(false)}}}
function familyPasswordAction(title,label,action){const d=familyDialog(title,`<form class="family-form">${familyPasswordField()}<p class="family-form-error" role="alert"></p><button class="primary family-save" type="submit">${esc(label)}</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const pw=familyGetPassword(d);d.setBusy(true);try{await action(pw);familyPin=pw;d.close()}catch(err){d.querySelector('.family-form-error').textContent=err.message||'저장하지 못했어요.'}finally{if(d.isConnected)d.setBusy(false)}};return d}
function familyOpenComplete(anchor){const data=familySession(anchor),expected=familySessionNote(anchor),next={...data,completed:!data.completed};familyPasswordAction(data.completed?'마침 취소':'마침 표시',data.completed?'마침 취소':'마침 표시',async pw=>{await familySaveMeta(anchor,next,pw,expected);await familyReloadNotes();if(location.hash===familySessionLink(anchor))familySessionView(anchor)})}
function familyOpenUpload(anchor,files){if(files.length>12||files.some(f=>f.size>25*1024*1024||!['image/jpeg','image/png','image/webp','image/gif'].includes(f.type))){alert('사진은 한 번에 최대 12장, 한 장당 25MB 이하의 JPG·PNG·WEBP·GIF 파일로 선택해 주세요. HEIC 사진은 JPG로 변환해 주세요.');return}const pending=files.slice(),d=familyDialog('사진',`<form class="family-form"><p class="family-upload-count">${files.length}장</p>${familyPasswordField()}<p class="family-form-error" role="alert"></p><button class="primary family-save" type="submit">올리기</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const pw=familyGetPassword(d),error=d.querySelector('.family-form-error');d.setBusy(true);let token=null;try{if(!familySessionNote(anchor)){await familySaveMeta(anchor,familyDefaults(anchor),pw,null);await familyReloadNotes()}while(pending.length){const file=pending[0],data=await compress(file).catch(()=>fileData(file));token=await issueUpload(pw);const filePath=await uploadData(data,token,0);await change('create',{person:'@family-photo:'+anchor,author:lastAuthor(),title:'사진',body:'family-photo:'+crypto.randomUUID(),book:FAMILY_PHOTO_BOOK,verse:'',topic:'',reference_url:'',images:[],file_paths:[filePath],upload_token:token},pw);token=null;pending.shift();d.querySelector('.family-upload-count').textContent=`${files.length-pending.length} / ${files.length}`;await familyReloadNotes()}familyPin=pw;d.close();if(location.hash===familySessionLink(anchor))familySessionView(anchor)}catch(err){if(token)await abandon(token);error.textContent=`${files.length-pending.length}장 완료 · ${pending.length}장 남음. `+(err.message||'사진을 올리지 못했어요.')+' 다시 올리기를 누르면 남은 사진부터 이어집니다.';if(location.hash===familySessionLink(anchor)&&pending.length<files.length)familySessionView(anchor)}finally{if(d.isConnected)d.setBusy(false)}}}
function familyPhotoActions(anchor,id){const pictures=familyPhotoNotes(anchor),index=pictures.findIndex(n=>n.id===id);if(index<0)return;const d=familyDialog('사진',`<div class="family-photo-actions"><button type="button" data-act="cover">대표 사진</button><button type="button" data-act="left" ${index===0?'disabled':''}>앞으로</button><button type="button" data-act="right" ${index===pictures.length-1?'disabled':''}>뒤로</button><button type="button" data-act="delete">삭제</button></div>`);d.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>{const action=b.dataset.act;d.close();if(action==='delete'){familyPasswordAction('사진 삭제','삭제',async pw=>{await change('delete',{id},pw);familyPhotoCache.delete(id);await familyReloadNotes();cleanup();if(location.hash===familySessionLink(anchor))familySessionView(anchor)});return}const data=familySession(anchor),expected=familySessionNote(anchor);if(action==='cover')data.cover=id;else{const order=pictures.map(x=>x.id),other=action==='left'?index-1:index+1;[order[index],order[other]]=[order[other],order[index]];data.order=order}(()=>{const save=async pw=>{await familySaveMeta(anchor,data,pw,expected);await familyReloadNotes();if(location.hash===familySessionLink(anchor))familySessionView(anchor)};if(familyPin)save(familyPin).catch(e=>alert(e.message||'사진을 정리하지 못했어요.'));else familyPasswordAction(action==='cover'?'대표 사진':'사진 순서','저장',save)})()})}

// Only refresh when the page is visible and no editing dialog is open.
let familyRefreshPending=false,lastFamilyRefresh=0;
async function familyRefreshVisible(force=false){if(document.hidden||familyRefreshPending||document.querySelector('dialog[open]')||document.activeElement?.id==='family-history-search'||!location.hash.startsWith('#/family'))return;if(!force&&Date.now()-lastFamilyRefresh<15000)return;const hash=location.hash,revision=familyRevision;familyRefreshPending=true;try{const fresh=await getAll('study_notes','id,person,author,title,body,created_at,updated_at,verse,book,topic,reference_url');if(!document.hidden&&!document.querySelector('dialog[open]')&&location.hash===hash&&revision===familyRevision){notes=fresh;lastFamilyRefresh=Date.now();if(hash.startsWith('#/family/session/'))familySessionView(decodeURIComponent(hash.split('/')[3]));else familyView()}}catch{}finally{familyRefreshPending=false}}
window.addEventListener('focus',()=>familyRefreshVisible());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)familyRefreshVisible(true)});
function familyRemoveSession(anchor){const n=familySessionNote(anchor);if(!n)return;const photos=familyPhotoNotes(anchor);if(!confirm(`이 회차와 사진 ${photos.length}장, 배운 점을 삭제할까요? 삭제한 내용은 되돌릴 수 없어요.`))return;familyPasswordAction('회차 삭제','삭제',async pw=>{let removed=0;try{for(const photo of familyPhotoNotes(anchor)){await change('delete',{id:photo.id},pw);familyPhotoCache.delete(photo.id);removed++;}await change('delete',{id:n.id},pw);await familyReloadNotes();cleanup();location.hash='#/family'}catch(e){await familyReloadNotes().catch(()=>{});throw Error(`사진 ${removed}장을 삭제했어요. 나머지는 다시 시도해 주세요. ${e.message||''}`)}})}

// Keep photo browsing separate from the general note-image viewer.
function familyOpenGallery(anchor,id){
 const pictures=familyPhotoNotes(anchor);let index=pictures.findIndex(n=>n.id===id),generation=0,startX=null;
 if(index<0)return;
 const d=document.createElement('dialog');d.className='family-gallery';d.setAttribute('aria-label','가족 숭배 사진');d.innerHTML=`<div class="family-gallery-inner"><button class="family-gallery-close" type="button" aria-label="닫기">${uiIcon('<path d="M18 6 6 18M6 6l12 12"/>')}</button><button class="family-gallery-prev" type="button" aria-label="이전 사진">${uiIcon('<path d="m15 18-6-6 6-6"/>')}</button><div class="family-gallery-stage"><img alt=""><p class="family-gallery-error" role="status"></p></div><button class="family-gallery-next" type="button" aria-label="다음 사진">${uiIcon('<path d="m9 18 6-6-6-6"/>')}</button><span class="family-gallery-count" aria-live="polite"></span></div>`;
 document.body.append(d);const img=d.querySelector('img'),error=d.querySelector('.family-gallery-error');
 const show=async()=>{const token=++generation;img.removeAttribute('src');img.alt=`가족 숭배 사진 ${index+1}`;error.textContent='';d.querySelector('.family-gallery-count').textContent=`${index+1} / ${pictures.length}`;d.querySelector('.family-gallery-prev').disabled=index===0;d.querySelector('.family-gallery-next').disabled=index===pictures.length-1;try{const src=await familyPhotoSource(pictures[index].id);if(token!==generation||!d.isConnected)return;if(!src)throw Error();img.src=src}catch{if(token===generation&&d.isConnected)error.textContent='사진을 불러오지 못했어요.'}};
 const move=step=>{const next=index+step;if(next>=0&&next<pictures.length){index=next;show()}};
 d.querySelector('.family-gallery-close').onclick=()=>d.close();d.querySelector('.family-gallery-prev').onclick=()=>move(-1);d.querySelector('.family-gallery-next').onclick=()=>move(1);d.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')move(-1);if(e.key==='ArrowRight')move(1)});const stage=d.querySelector('.family-gallery-stage');stage.addEventListener('touchstart',e=>{startX=e.touches.length===1?e.touches[0].clientX:null},{passive:true});stage.addEventListener('touchend',e=>{if(startX===null||!e.changedTouches.length)return;const delta=e.changedTouches[0].clientX-startX;startX=null;if(Math.abs(delta)>55)move(delta<0?1:-1)},{passive:true});d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();show();
}

// A single save updates the photo order and cover together.
function familyArrangePhotos(anchor){
 const original=familyPhotoNotes(anchor),data=familySession(anchor),expected=familySessionNote(anchor);if(original.length<2||!expected)return;
 let order=original.map(n=>n.id),cover=data.cover||order[0];const initialOrder=order.slice(),initialCover=cover;
 const d=familyDialog('사진 정리',`<form class="family-form family-arrange-form"><div class="family-arrange-grid"></div>${familyPasswordField()}<p class="family-form-error" role="alert"></p><button class="primary family-save" type="submit">저장</button></form>`),grid=d.querySelector('.family-arrange-grid');
 d.isDirty=()=>cover!==initialCover||order.some((id,i)=>id!==initialOrder[i]);
 const move=(from,to)=>{if(from<0||to<0||from>=order.length||to>=order.length||from===to)return;const [id]=order.splice(from,1);order.splice(to,0,id);render()};
 function render(){grid.innerHTML=order.map((id,i)=>`<div class="family-arrange-item" data-order-index="${i}"><img data-family-photo-src="${esc(id)}" alt="사진 ${i+1}" hidden><button type="button" class="family-arrange-cover ${cover===id?'is-cover':''}" data-cover="${i}" aria-label="${cover===id?'대표 사진':'대표 사진으로 선택'}" aria-pressed="${cover===id}">${uiIcon('<path d="m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1-4.4-4.3 6.1-.9Z"/>')}</button><div class="family-arrange-controls"><button type="button" data-move="${i}:-1" aria-label="사진 ${i+1} 앞으로 이동" ${i===0?'disabled':''}>${uiIcon('<path d="m15 18-6-6 6-6"/>')}</button><button type="button" class="family-drag-handle" data-drag="${i}" aria-label="사진 ${i+1} 끌어서 이동">${uiIcon('<path d="M9 5h.01M15 5h.01M9 12h.01M15 12h.01M9 19h.01M15 19h.01"/>')}</button><button type="button" data-move="${i}:1" aria-label="사진 ${i+1} 뒤로 이동" ${i===order.length-1?'disabled':''}>${uiIcon('<path d="m9 18 6-6-6-6"/>')}</button></div></div>`).join('');familyFillPhotos(grid);
 grid.querySelectorAll('[data-cover]').forEach(b=>b.onclick=()=>{cover=order[Number(b.dataset.cover)];render()});grid.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const [i,delta]=b.dataset.move.split(':').map(Number);move(i,i+delta)});grid.querySelectorAll('[data-drag]').forEach(handle=>{handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();handle.setPointerCapture(e.pointerId);handle.classList.add('is-dragging')});handle.addEventListener('pointerup',e=>{const source=Number(handle.dataset.drag),target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-order-index]');handle.classList.remove('is-dragging');if(target&&grid.contains(target))move(source,Number(target.dataset.orderIndex))});handle.addEventListener('pointercancel',()=>handle.classList.remove('is-dragging'))});
 }
 render();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const pw=familyGetPassword(d);if(!d.isDirty()){d.close();return}d.setBusy(true);d.querySelector('.family-form-error').textContent='';try{await familySaveMeta(anchor,{...data,cover,order},pw,expected);familyPin=pw;await familyReloadNotes();d.close();if(location.hash===familySessionLink(anchor))familySessionView(anchor)}catch(err){d.querySelector('.family-form-error').textContent=err.message||'사진을 정리하지 못했어요.';if(/다른 기기/.test(err.message||''))await familyReloadNotes().catch(()=>{})}finally{if(d.isConnected)d.setBusy(false)}};
}
